import json
import os

def validate_files():
    files_to_check = [
        "outputs/t01_selected_indicators.csv",
        "outputs/t05_clean_stops.csv",
        "outputs/t08_pois_clean.csv",
        "outputs/t10_accessibility_scores.csv",
        "outputs/t13_city_clusters.csv"
    ]

    results = []

    for file_path in files_to_check:
        check_name = f"Check existence and non-empty status of {file_path}"

        if not os.path.exists(file_path):
            results.append({
                "check_name": check_name,
                "passed": False,
                "message": f"File {file_path} does not exist."
            })
        elif os.path.getsize(file_path) == 0:
            results.append({
                "check_name": check_name,
                "passed": False,
                "message": f"File {file_path} is empty."
            })
        else:
            results.append({
                "check_name": check_name,
                "passed": True,
                "message": f"File {file_path} is present and not empty."
            })

    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(results, f, indent=2)

if __name__ == "__main__":
    validate_files()

